cat << 'EOF' > /tmp/analyze_binlog.cs
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild("/tmp/sv-6115c843941541ce958eccdb44613717/build.binlog");

Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

// Collect all errors
var errors = new List<(string project, string code, string message, string file, int line)>();

build.VisitAllChildren<Error>(error => {
    var project = "";
    var node = error.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((project, error.Code ?? "", error.Message ?? "", error.File ?? "", error.LineNumber));
});

Console.WriteLine($"Total errors: {errors.Count}\n");

var grouped = errors.GroupBy(e => e.project);
foreach (var g in grouped.OrderBy(x => x.Key)) {
    Console.WriteLine($"--- Project: {g.Key} ---");
    foreach (var e in g) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
    Console.WriteLine();
}

// Also look for warnings that might be relevant
var warnings = new List<(string project, string code, string message)>();
build.VisitAllChildren<Warning>(w => {
    var project = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    if (w.Code != null && (w.Code.StartsWith("NU") || w.Code.StartsWith("MSB")))
        warnings.Add((project, w.Code, w.Message ?? ""));
});

if (warnings.Any()) {
    Console.WriteLine("=== RELEVANT WARNINGS ===");
    foreach (var w in warnings.Take(20)) {
        Console.WriteLine($"  [{w.code}] ({w.project}): {w.message}");
    }
}
EOF
